body.raw:
{
  "v": 1,
  "id": "{{$guid}}",
  "runId": "{{runId}}",
  "seq": {{seq}},
  "type": "message.done",
  "ts": "{{$isoTimestamp}}",
  "payload": {
    "messageId": "pm-{{seq}}",
    "text": "Hello from **Postman**.\n\n- signed with the callback secret\n- delivered by gd-api in seq order",
    "format": "markdown"
  }
}

{
  "v": 1,
  "id": "{{$guid}}",
  "runId": "{{runId}}",
  "seq": {{seq}},
  "type": "ui.render",
  "ts": "{{$isoTimestamp}}",
  "payload": {
    "uiId": "pm-card-{{seq}}",
    "surface": "inline",
    "schema": 1,
    "tree": {
      "id": "card",
      "type": "card",
      "props": {
        "title": "Sent from Postman",
        "subtitle": "ui.render · surface inline",
        "tone": "info"
      },
      "children": [
        {
          "id": "kv",
          "type": "kv",
          "props": {
            "items": [
              {
                "label": "Patient",
                "value": "Maya Patel"
              },
              {
                "label": "Next visit",
                "value": "24 Oct 2026"
              }
            ]
          }
        },
        {
          "id": "flags",
          "type": "row",
          "props": {
            "gap": "sm"
          },
          "children": [
            {
              "id": "b1",
              "type": "badge",
              "props": {
                "text": "HbA1c high",
                "tone": "danger"
              }
            },
            {
              "id": "b2",
              "type": "badge",
              "props": {
                "text": "BP normal",
                "tone": "success"
              }
            }
          ]
        },
        {
          "id": "ok",
          "type": "button",
          "props": {
            "label": "Acknowledge",
            "actionId": "ack"
          }
        }
      ]
    }
  }
}

{
  "v": 1,
  "id": "{{$guid}}",
  "runId": "{{runId}}",
  "seq": {{seq}},
  "type": "run.error",
  "ts": "{{$isoTimestamp}}",
  "payload": {
    "code": "postman_test",
    "message": "This error was sent from Postman.",
    "retryable": true
  }
}
